// === Tab: mySketch ===
function setup(){
  createCanvas(1400, 900);
}
function draw(){
  background(0);
  smooth();
  let angle = 0.0;
  let scaleVal = ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))/7.5)/5;
  let i = 6;
  println(i);
  let angleInc = PI/i;
  let w = 20/1.5;
  fill(255);
  for (y=0; y<= height+w; y+=w){
    stroke(0);
    line(0,y,900,y);
  }

  for (offset = 0; offset<width+w; offset +=w*2){
    angle = 0.0;
    //noStroke();
    for (y=0; y<= height; y+=w){
      let x = offset + (sin(angle)*scaleVal);
      rect(x,y,w,w);
      angle += angleInc;
    }
  }
  if (mousePressed){
    background(0);
    var x = 0;
    let y = 0;
    stroke(0);

    let scl = w*(abs(x-(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))))/width*1+0.15);
    let count = 0;
    for (x=0; x<width; x+=scl){
      scl = w*(abs(x-(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))))/width*1.4+0.15);
      if (scl>w){scl=w;}
      if (count%2==0){
        for (y = 0; y<height; y+=w*2){
        fill(255);
        rect(x,y,scl/2,w/2);
      }
      } else {
        for (y = w; y<height; y+=w*2){
        fill(255);
        rect(x,y,scl/2,w/2);
      }
      }
      count ++;
    }
  }
}

